<?php

declare(strict_types=1);

namespace NoResponse\LateResults;

/**
 * The provider refused an action or could not be reached (status 0). Answer the webhook with a 5xx so it is
 * delivered again. Generated by tools/generate_overlays.py; do not edit.
 */
final class ProviderActionException extends \RuntimeException
{
    /**
     * @param  ?string  $errorCode  The provider's error code, such as Auth0's errorCode "insufficient_scope", when it sent one.
     */
    public function __construct(
        public readonly string $provider,
        public readonly int $status,
        string $message,
        public readonly ?string $errorCode = null,
        ?\Throwable $previous = null,
    ) {
        parent::__construct($message, 0, $previous);
    }
}
